{
      "id": "qftx-gauge-slice-mathematics-examples",
      "title": "Local Gauge Slices and Faddeev–Popov Jacobians — Examples",
      "kind": "B",
      "category": "quantum-field-theory-mathematics",
      "library": "mathematics",
