      "items": [
        {
          "id": "ex-qftx-translation-gauge-slice-jacobian",
          "kind": "example",
          "domain": "mathematics",
          "title": "Translation action with a unit Faddeev–Popov Jacobian",
          "reference": "items/ex-qftx-translation-gauge-slice-jacobian.md",
          "design_state": "Step 1 draft authored; item readiness is recorded separately. The planned Singer theorem has no carrier and remains explicitly escalated in batch evidence.",
          "dependency_level": 4,
          "deps": [
            "def-qftx-gauge-slice-and-faddeev-popov-operator",
            "thm-qftx-local-faddeev-popov-slice-jacobian"
          ],
          "dependency_roles": {
            "def-qftx-gauge-slice-and-faddeev-popov-operator": "mathematical-premise",
            "thm-qftx-local-faddeev-popov-slice-jacobian": "mathematical-premise"
          },
          "inventory_expansion_required": false,
          "statement": "Take $M=\\{\\star\\}$ and\n$$G=SU(2):=\\{q\\in M_2(\\mathbb C):q^*q=I_2,\\ \\det q=1\\}$$\nwith matrix multiplication and Lie algebra $\\mathfrak{su}(2)=\\{Z\\in M_2(\\mathbb C):Z^*=-Z,\\ \\operatorname{tr}Z=0\\}$. Its elements are exactly $\\begin{pmatrix}a&b\\\\-\\overline b&\\overline a\\end{pmatrix}$ with $|a|^2+|b|^2=1$, giving a diffeomorphism with the unit sphere in $\\mathbb C^2$; matrix multiplication and inversion are smooth. Thus $G$ is a compact noncommutative finite-dimensional real Lie group, as checked in the Verification. Let $P=SU(2)\\to M$ with right multiplication, $H=0$, and $\\omega_q(V)=q^{-1}V$ for $V\\in T_qSU(2)$; this specifies the principal bundle and connection datum. Choose the independent regulator $X=\\mathbb R^2$ with coordinates $(u,v)$ and density $du\\,dv$, the additive Lie group $K=(\\mathbb R,+)$ with left-invariant density $dt$, and the smooth right action\n$$\n(u,v)\\cdot t=(u+t,v).\n$$\nLet $S=\\{(0,v):v\\in\\mathbb R\\}$, choose $s_0=(0,0)\\in S$, and set $U=X$. Let $\\chi(u,v)=u$ and give $S$ density $dv$. For every $s=(0,v)\\in S$, the Faddeev–Popov operator is $M_s(t)=t$, so $\\Delta_{\\mathrm{FP}}(s)=1$. The local orbit-to-slice map is $\\Psi(t,(0,v))=(t,v)$, with density Jacobian $1$. For $x=(a,b)$, the gauge condition along its orbit is $F_x(t)=a+t$; it has one transverse zero $t_0=-a$, and the slice meets this orbit once. If $\\Gamma\\subset\\mathbb R$ is relatively compact and open with $t_0\\in\\Gamma$, and $\\varphi\\in C_c^\\infty(\\Gamma)$ has $t_0\\in\\operatorname{supp}\\varphi$, then for every nonnegative compactly supported smooth $\\eta$ of integral $1$, the regularized intersection expression tends to $\\varphi(t_0)$.",
          "provenance": {
            "statement": "ai-generated",
            "proof": "ai-generated"
          },
          "sources": {
            "references": [
              {
                "title": "David Skinner, Quantum Field Theory II: Advanced Quantum Field Theory lecture notes, Chapter 8",
                "url": "https://www.damtp.cam.ac.uk/user/dbs26/AQFT/chap8.pdf",
                "locator": "§§8.1–8.1.1, PDF pp. 154–161: finite-dimensional slice Jacobians and the boundary between regulator calculations and continuum gauge fixing."
              }
            ]
          },
          "library": "mathematics",
          "proof_strategy": "direct",
          "generation": {
            "role": "example"
          },
          "axiom_base": "ZF + AC_omega inherited from the regulated gauge-slice datum.",
          "category": "quantum-field-theory-mathematics"
        },
        {
          "id": "ex-qftx-so2-gauge-slice-multiplicity",
          "kind": "example",
          "domain": "mathematics",
          "title": "SO(2) orbit with two slice intersections and a stabilizer at the origin",
          "reference": "items/ex-qftx-so2-gauge-slice-multiplicity.md",
          "design_state": "Step 1 draft authored; item readiness is recorded separately. The planned Singer theorem has no carrier and remains explicitly escalated in batch evidence.",
          "dependency_level": 4,
          "deps": [
            "def-qftx-gauge-slice-and-faddeev-popov-operator",
            "thm-qftx-local-faddeev-popov-slice-jacobian"
          ],
          "dependency_roles": {
            "def-qftx-gauge-slice-and-faddeev-popov-operator": "mathematical-premise",
            "thm-qftx-local-faddeev-popov-slice-jacobian": "mathematical-premise"
          },
          "inventory_expansion_required": false,
          "statement": "Take $M=\\{\\star\\}$ and\n$$G=SU(2):=\\{q\\in M_2(\\mathbb C):q^*q=I_2,\\ \\det q=1\\}$$\nwith matrix multiplication and Lie algebra $\\mathfrak{su}(2)=\\{Z\\in M_2(\\mathbb C):Z^*=-Z,\\ \\operatorname{tr}Z=0\\}$. Its elements are exactly $\\begin{pmatrix}a&b\\\\-\\overline b&\\overline a\\end{pmatrix}$ with $|a|^2+|b|^2=1$, giving a diffeomorphism with the unit sphere in $\\mathbb C^2$; matrix multiplication and inversion are smooth. Thus $G$ is a compact noncommutative finite-dimensional real Lie group, as checked in the Verification. Let $P=SU(2)\\to M$ with right multiplication, $H=0$, and $\\omega_q(V)=q^{-1}V$ for $V\\in T_qSU(2)$; this specifies the principal bundle and connection datum. Choose the independent regulator $X=\\mathbb R^2$ with Lebesgue density. Write $R_\\theta=\\begin{pmatrix}\\cos\\theta&-\\sin\\theta\\\\\\sin\\theta&\\cos\\theta\\end{pmatrix}\\in SO(2)$ for $\\theta\\in\\mathbb R/(2\\pi\\mathbb Z)$. Let $K=SO(2)$ with left-invariant density $|d\\theta|$, and define the smooth right action\n$$\n(x,y)\\cdot R_\\theta=(x\\cos\\theta+y\\sin\\theta,\\,-x\\sin\\theta+y\\cos\\theta).\n$$\nTake $S=\\{(x,0):x\\in\\mathbb R\\}$, choose $s_0=(1,0)\\in S$, and set $U=X$. Let $\\chi(x,y)=y$ and give $S$ density $dx$. At $s=(r,0)$, the orbit differential in the angle direction is $(0,-r)$, so $M_s(1)=-r$ and $\\Delta_{\\mathrm{FP}}(s)=|r|$. For $r>0$, the orbit-to-slice map is $\\Psi(R_\\theta,(r,0))=(r\\cos\\theta,-r\\sin\\theta)$, whose coordinate Jacobian at the identity is $r$, agreeing with the Faddeev–Popov density ratio. For a fixed orbit point $x_0=(r,0)$, $r>0$, the gauge function is $F_{x_0}(R_\\theta)=-r\\sin\\theta$. Its two zeros are $\\theta=0,\\pi$, with distinct slice points $(r,0)$ and $(-r,0)$, and both are transverse. Taking $\\Gamma=SO(2)$ and the test function $\\varphi=1$, the regularized intersection expression tends to $2$. At the origin the full group stabilizes the point, $M_{(0,0)}=0$, and $F_{(0,0)}$ vanishes on all of $SO(2)$; the theorem's isolated transverse-zero hypotheses fail there.",
          "provenance": {
            "statement": "ai-generated",
            "proof": "ai-generated"
          },
          "sources": {
            "references": [
              {
                "title": "David Skinner, Quantum Field Theory II: Advanced Quantum Field Theory lecture notes, Chapter 8",
                "url": "https://www.damtp.cam.ac.uk/user/dbs26/AQFT/chap8.pdf",
                "locator": "§§8.1–8.1.1, PDF pp. 154–161: the SO(2) orbit model, multiple intersections, and the vanishing Faddeev–Popov derivative at a stabilizer."
              }
            ]
          },
          "library": "mathematics",
          "proof_strategy": "direct",
          "generation": {
