        {
          "id": "thm-aqft-finite-group-gauging",
          "kind": "theorem",
          "domain": "mathematics",
          "title": "Finite cocycle-weighted groupoid gauging and gluing",
          "reference": "items/thm-aqft-finite-group-gauging.md",
          "design_state": "Step 1 authored; conditional two-group prerequisite status and current readiness are recorded in the batch notes and Step-1 receipt.",
          "dependency_level": 5,
          "deps": [
            "def-aqft-background-gauging-data",
