        {
          "id": "ex-aqft-z2-topological-defect-finite-quantum-mechanics",
          "kind": "example",
          "domain": "physics",
          "library": "physics",
          "category": "advanced-qft-and-supersymmetry",
          "title": "A nontrivial Z2 topological defect in finite quantum mechanics",
          "reference": "items/ex-aqft-z2-topological-defect-finite-quantum-mechanics.md",
          "design_state": "Owner-directed B-page finite-model example or counterexample, proved locally; no empirical or continuum claim.",
          "dependency_level": 2,
