          "title": "Charge-one BPST instanton on the round four-sphere",
          "reference": "items/ex-qftx-su2-bpst-one-instanton.md",
          "design_state": "Step 1 ready; current prerequisites, placement, proof contract, and scoped checks recorded.",
          "dependency_level": 5,
