        {
          "id": "lem-aqft-dual-cubic-anomaly-polynomial-cancellation",
          "kind": "lemma",
          "domain": "mathematics",
          "title": "A conjugate representation reverses the cubic anomaly polynomial",
          "reference": "items/lem-aqft-dual-cubic-anomaly-polynomial-cancellation.md",
          "design_state": "Step 1 authored; current interface, source evidence, and readiness are recorded in batch-41 notes.",
