        {
          "id": "lem-equivariant-relative-tangent-groupoid-heat-trace-limit",
          "kind": "lemma",
          "domain": "mathematics",
          "library": "mathematics",
          "title": "Relative tangent-groupoid heat-trace limit at simple fixed points",
          "dependency_level": 1,
          "deps": [
